using Microsoft.AspNetCore.Mvc;using Microsoft.EntityFrameworkCore;using Ordella_deliverable2.Data;using Ordella_deliverable2.Models;
namespace Ordella_deliverable2.Controllers;
public class OrderController:Controller
{private readonly ApplicationDbContext db;public OrderController(ApplicationDbContext d){db=d;}[HttpGet] public async Task<IActionResult> Checkout(int shopId){var shop=await db.Shops.FirstOrDefaultAsync(s=>s.Id==shopId&&s.IsPublished);if(shop==null)return NotFound();ViewBag.Shop=shop;return View(new CheckoutViewModel());}
 [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> Checkout(int shopId,CheckoutViewModel model){var shop=await db.Shops.Include(s=>s.Products).FirstOrDefaultAsync(s=>s.Id==shopId&&s.IsPublished);if(shop==null)return NotFound();ViewBag.Shop=shop;if(!ModelState.IsValid)return View(model);var available=shop.Products.Where(p=>p.IsAvailable).ToList();if(!available.Any()){ModelState.AddModelError("","This shop currently has no available products.");return View(model);}var order=new CustomerOrder{ShopId=shop.Id,CustomerName=model.CustomerName,CustomerEmail=model.CustomerEmail,CustomerPhone=model.CustomerPhone,Notes=model.Notes,Total=available.Sum(p=>p.Price),Items=available.Select(p=>new OrderItem{ProductId=p.Id,ProductName=p.Name,UnitPrice=p.Price,Quantity=1}).ToList()};db.Orders.Add(order);await db.SaveChangesAsync();return RedirectToAction(nameof(Confirmation),new{id=order.Id});}
 public async Task<IActionResult> Confirmation(int id){var o=await db.Orders.FirstOrDefaultAsync(x=>x.Id==id);return o==null?NotFound():View(o);}}
